import os
import json
import asyncio
from typing import List, Dict, Any
from flask import Flask, request, jsonify, send_from_directory
from flask_cors import CORS
from exa_py import Exa
from cerebras.cloud.sdk import Cerebras
from openai import OpenAI

app = Flask(__name__, static_folder='.')
CORS(app)

# API inicializálás
exa = Exa(os.environ.get('EXA_API_KEY'))
cerebras = Cerebras(api_key=os.environ.get('CEREBRAS_API_KEY'))
grok = OpenAI(
    api_key=os.environ.get('XAI_API_KEY'),
    base_url="https://api.x.ai/v1"
)

class JadeResearchEngine:
    def __init__(self):
        self.research_depth = 5
        self.max_sources = 1000

    async def analyze_query(self, query: str) -> Dict[str, Any]:
        """Elemzi a kérdést és több modell együttműködik"""
        # Grok 4 Fast - gyors előzetes elemzés
        analysis = grok.chat.completions.create(
            model="grok-4-fast-reasoning",
            messages=[{
                "role": "system",
                "content": "Te Jade vagy. Elemezz lekérdezéseket és dönts el, milyen kutatási stratégia szükséges."
            }, {
                "role": "user",
                "content": f"Elemezd ezt a kérdést és határozd meg a kutatási irányt: {query}"
            }],
            temperature=0.3
        )

        strategy = analysis.choices[0].message.content

        # Cerebras Qwen 3 235B Thinking - mélyebb reasoning
        reasoning = cerebras.chat.completions.create(
            model="qwen-3-235b-a22b-thinking-2507",
            messages=[{
                "role": "system",
                "content": "Te Jade vagy. Gondolkozz el a kutatási megközelítésen."
            }, {
                "role": "user",
                "content": f"Stratégia: {strategy}\nKérdés: {query}\n\nHatározd meg: milyen kulcsszavakat, forrásokat, időszakokat használjak?"
            }],
            temperature=0.4
        )

        return {
            "strategy": strategy,
            "reasoning": reasoning.choices[0].message.content,
            "query": query
        }

    async def multi_stage_search(self, analysis: Dict[str, Any]) -> List[Dict]:
        """Többlépcsős, intelligens keresés"""
        all_sources = []
        query = analysis["query"]
        reasoning = analysis["reasoning"]

        # 1. szakasz: Neurális keresés széles spektrumban
        initial_search = exa.search_and_contents(
            query=query,
            type="neural",
            num_results=100,
            text={"max_characters": 2000},
            highlights=True,
            livecrawl="preferred"
        )
        all_sources.extend(self._format_results(initial_search.results))

        # 2. szakasz: Kulcsszavas keresés specifikus domaineken
        domains = ["arxiv.org", "scholar.google.com", "github.com", "news.ycombinator.com"]
        for domain in domains:
            try:
                domain_search = exa.search_and_contents(
                    query=query,
                    type="keyword",
                    include_domains=[domain],
                    num_results=50,
                    text=True,
                    livecrawl="preferred"
                )
                all_sources.extend(self._format_results(domain_search.results))
            except:
                pass

        # 3. szakasz: Hasonló források feltérképezése
        if len(all_sources) > 0:
            for src in all_sources[:10]:
                try:
                    similar = exa.find_similar_and_contents(
                        url=src["url"],
                        num_results=20,
                        text=True
                    )
                    all_sources.extend(self._format_results(similar.results))
                except:
                    pass

        # 4. szakasz: LiveCrawl mindig friss adatokkal
        live_results = exa.search_and_contents(
            query=f"{query} latest news updates 2025",
            type="fast",
            num_results=100,
            livecrawl="always",
            text=True,
            category="news"
        )
        all_sources.extend(self._format_results(live_results.results))

        # 5. szakasz: Research API mély elemzés
        try:
            research_task = exa.research.create_task(
                instructions=f"Kutatás témája: {query}. {reasoning}",
                output_schema={
                    "type": "object",
                    "properties": {
                        "key_findings": {"type": "array", "items": {"type": "string"}},
                        "sources": {"type": "array", "items": {"type": "string"}},
                        "confidence": {"type": "string"}
                    }
                },
                model="exa-research-pro"
            )
            research_result = exa.research.poll_task(research_task.id, max_wait_time=300)
            if research_result.status == "completed":
                all_sources.append({
                    "type": "research_synthesis",
                    "data": research_result.data,
                    "citations": research_result.citations
                })
        except:
            pass

        # Deduplikálás
        unique_sources = self._deduplicate(all_sources)
        return unique_sources[:self.max_sources]

    def _format_results(self, results):
        """Eredmények formázása"""
        formatted = []
        for r in results:
            formatted.append({
                "url": r.url,
                "title": getattr(r, 'title', ''),
                "text": getattr(r, 'text', ''),
                "highlights": getattr(r, 'highlights', []),
                "published_date": getattr(r, 'published_date', ''),
                "author": getattr(r, 'author', '')
            })
        return formatted

    def _deduplicate(self, sources: List[Dict]) -> List[Dict]:
        """URL alapú deduplikálás"""
        seen = set()
        unique = []
        for src in sources:
            url = src.get("url", "")
            if url and url not in seen:
                seen.add(url)
                unique.append(src)
        return unique

    async def synthesize_answer(self, query: str, sources: List[Dict]) -> str:
        """Válasz szintézis több modell együttműködésével"""
        # Források szövegének összegyűjtése
        context = "\n\n".join([
            f"[{i+1}] {s.get('title', 'No title')}\n{s.get('text', '')[:1000]}"
            for i, s in enumerate(sources[:50])
        ])

        # Cerebras GPT-OSS-120B - gyors összefoglalás
        cerebras_summary = cerebras.chat.completions.create(
            model="gpt-oss-120b",
            messages=[{
                "role": "system",
                "content": "Te Jade vagy. Fogalmazz szakértőként, magyarázd el világosan."
            }, {
                "role": "user",
                "content": f"Kérdés: {query}\n\nForrások:\n{context}\n\nÍrj átfogó választ."
            }],
            temperature=0.6,
            max_tokens=2000
        )

        summary = cerebras_summary.choices[0].message.content

        # Grok 4 - végső polírás reasoning-gel
        final_answer = grok.chat.completions.create(
            model="grok-4-0709",
            messages=[{
                "role": "system",
                "content": "Te Jade vagy, egy intelligens kutatóasszisztens. Finomítsd ezt a választ, add hozzá a saját reasoning-edet."
            }, {
                "role": "user",
                "content": f"Kérdés: {query}\n\nElőzetes összefoglaló:\n{summary}\n\nForrások száma: {len(sources)}\n\nKészíts professzionális, részletes választ hivatkozásokkal."
            }],
            temperature=0.7
        )

        return final_answer.choices[0].message.content

    async def research(self, query: str) -> Dict[str, Any]:
        """Teljes kutatási folyamat"""
        # 1. Elemzés
        analysis = await self.analyze_query(query)

        # 2. Többlépcsős keresés
        sources = await self.multi_stage_search(analysis)

        # 3. Válasz szintézis
        answer = await self.synthesize_answer(query, sources)

        return {
            "answer": answer,
            "sources_count": len(sources),
            "sources": sources[:100],  # Első 100 forrás visszaküldése
            "analysis": analysis
        }

jade_engine = JadeResearchEngine()

@app.route('/')
def index():
    return send_from_directory('.', 'index.html')

@app.route('/api/search', methods=['POST'])
def search():
    data = request.json
    query = data.get('query', '')

    if not query:
        return jsonify({"error": "Nincs kérdés megadva"}), 400

    try:
        # Asyncio futtatás szinkron kontextusban
        loop = asyncio.new_event_loop()
        asyncio.set_event_loop(loop)
        result = loop.run_until_complete(jade_engine.research(query))
        loop.close()

        return jsonify(result)
    except Exception as e:
        return jsonify({"error": str(e)}), 500

@app.route('/api/stream', methods=['POST'])
def stream_search():
    """Streaming válasz (opcionális)"""
    data = request.json
    query = data.get('query', '')

    def generate():
        try:
            # Gyors válasz Cerebras-szal
            stream = cerebras.chat.completions.create(
                model="gpt-oss-120b",
                messages=[{
                    "role": "system",
                    "content": "Te Jade vagy."
                }, {
                    "role": "user",
                    "content": f"Válaszolj röviden: {query}"
                }],
                stream=True,
                temperature=0.7
            )

            for chunk in stream:
                if chunk.choices[0].delta.content:
                    yield f"data: {json.dumps({'content': chunk.choices[0].delta.content})}\n\n"

            yield "data: [DONE]\n\n"
        except Exception as e:
            yield f"data: {json.dumps({'error': str(e)})}\n\n"

    return app.response_class(generate(), mimetype='text/event-stream')

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000, debug=False)


