<body>
    <div class="hero">
        <div class="logo">Jade</div>
        <div class="tagline">Intelligens Kutatóasszisztens</div>
        <div class="subtitle">Több ezer forrás, egy válasz</div>
    </div>

    <div class="container">
        <div class="search-container">
            <div class="input-wrapper">
                <input 
                    type="text" 
                    id="queryInput" 
                    placeholder="Kérdezz bármit..." 
                    autocomplete="off"
                >
            </div>
            <button class="search-btn" id="searchBtn">Kutatás indítása</button>
        </div>

        <div class="loader" id="loader">
            <div class="spinner"></div>
        </div>

        <div class="results" id="results">
            <div class="answer-box">
                <div class="answer-header">
                    <div class="answer-icon">✨</div>
                    <div class="answer-title">Jade válasza</div>
                </div>
                <div class="answer-content" id="answerContent"></div>
            </div>

            <div class="sources-section">
                <div class="sources-header">
                    Források
                    <span class="source-count" id="sourceCount">0</span>
                </div>
                <div id="sourcesList"></div>
            </div>
        </div>
    </div>

    <div class="footer">
        © 2025 Jade • Powered by Cerebras, Grok, Qwen & Exa
    </div>

    <script>
        const queryInput = document.getElementById('queryInput');
        const searchBtn = document.getElementById('searchBtn');
        const loader = document.getElementById('loader');
        const results = document.getElementById('results');
        const answerContent = document.getElementById('answerContent');
        const sourcesList = document.getElementById('sourcesList');
        const sourceCount = document.getElementById('sourceCount');

        searchBtn.addEventListener('click', performSearch);
        queryInput.addEventListener('keypress', (e) => {
            if (e.key === 'Enter') performSearch();
        });

        async function performSearch() {
            const query = queryInput.value.trim();
            if (!query) return;

            // UI Reset
            searchBtn.disabled = true;
            searchBtn.textContent = 'Kutatás folyamatban...';
            loader.classList.add('active');
            results.classList.remove('active');

            try {
                const response = await fetch('/api/search', {
                    method: 'POST',
                    headers: {
                        'Content-Type': 'application/json'
                    },
                    body: JSON.stringify({ query })
                });

                const data = await response.json();

                if (data.error) {
                    alert('Hiba: ' + data.error);
                    return;
                }

                // Render Answer
                answerContent.textContent = data.answer;

                // Render Sources
                sourceCount.textContent = data.sources_count;
                sourcesList.innerHTML = '';

                data.sources.forEach((source, index) => {
                    const sourceItem = document.createElement('div');
                    sourceItem.className = 'source-item';
                    sourceItem.innerHTML = `
                        <div class="source-title">[${index + 1}] ${source.title || 'Nincs cím'}</div>
                        <a href="${source.url}" target="_blank" class="source-url">${source.url}</a>
                        ${source.text ? `<div class="source-text">${source.text.substring(0, 300)}...</div>` : ''}
                    `;
                    sourcesList.appendChild(sourceItem);
                });

                results.classList.add('active');
                results.scrollIntoView({ behavior: 'smooth', block: 'nearest' });

            } catch (error) {
                alert('Hiba történt: ' + error.message);
            } finally {
                searchBtn.disabled = false;
                searchBtn.textContent = 'Kutatás indítása';
                loader.classList.remove('active');
            }
        }
    </script>
</body>
</html>




